begin;
create extension if not exists pgtap with schema extensions;
select plan(6);
insert into auth.users(id,email) values ('50000000-0000-0000-0000-000000000001','file-teacher@example.test'),('50000000-0000-0000-0000-000000000002','file-student@example.test');
update lms.profiles set role='teacher' where id='50000000-0000-0000-0000-000000000001';
update lms.profiles set assessment_completed=true where id='50000000-0000-0000-0000-000000000002';
insert into lms.courses(id,title,teacher_id,published) values('51000000-0000-0000-0000-000000000001','Files','50000000-0000-0000-0000-000000000001',true);
insert into lms.enrollments values('51000000-0000-0000-0000-000000000001','50000000-0000-0000-0000-000000000002','approved');
insert into lms.lessons(id,course_id,title,position,published) values('52000000-0000-0000-0000-000000000001','51000000-0000-0000-0000-000000000001','Files',1,true);
insert into lms.revisions(id,lesson_id,title,position,content) select revision_id,'52000000-0000-0000-0000-000000000001','Files',1,jsonb_build_array(jsonb_build_object('id','v','styles',jsonb_build_array('visual'),'blocks',jsonb_build_array(jsonb_build_object('id','b','type','image','url','/api/lms/files?path=51000000-0000-0000-0000-000000000001%2F52000000-0000-0000-0000-000000000001%2F'||filename)))) from (values ('53000000-0000-0000-0000-000000000001'::uuid,'pinned.png'),('53000000-0000-0000-0000-000000000002'::uuid,'published.png'),('53000000-0000-0000-0000-000000000003'::uuid,'draft.png')) fixture(revision_id,filename);
update lms.lessons set current_revision_id='53000000-0000-0000-0000-000000000002',draft_revision_id='53000000-0000-0000-0000-000000000003' where id='52000000-0000-0000-0000-000000000001';
insert into lms.lesson_progress(student_id,lesson_id,revision_id) values('50000000-0000-0000-0000-000000000002','52000000-0000-0000-0000-000000000001','53000000-0000-0000-0000-000000000001');
insert into storage.objects(bucket_id,name) select 'lms-files','51000000-0000-0000-0000-000000000001/52000000-0000-0000-0000-000000000001/'||filename from (values ('pinned.png'),('published.png'),('draft.png')) fixture(filename);
set local role authenticated;
select set_config('request.jwt.claim.sub','50000000-0000-0000-0000-000000000002',true);
select is((select count(*)::integer from storage.objects where bucket_id='lms-files' and name like '%/pinned.png'),1,'student reads media referenced by pinned revision');
select is((select count(*)::integer from storage.objects where bucket_id='lms-files' and name like '%/draft.png'),0,'student cannot list or sign draft-only media');
select is((select count(*)::integer from storage.objects where bucket_id='lms-files' and name like '%/published.png'),0,'pinned student cannot read newer revision media');
select set_config('request.jwt.claim.sub','50000000-0000-0000-0000-000000000001',true);
select is((select count(*)::integer from storage.objects where bucket_id='lms-files'),3,'owner can read all course media');
reset role;
delete from lms.lesson_progress where student_id='50000000-0000-0000-0000-000000000002';
set local role authenticated;
select set_config('request.jwt.claim.sub','50000000-0000-0000-0000-000000000002',true);
select is((select count(*)::integer from storage.objects where bucket_id='lms-files' and name like '%/published.png'),1,'before pinning student can access current published media');
select is((select count(*)::integer from storage.objects where bucket_id='lms-files' and name like '%/draft.png'),0,'unstarted student still cannot read draft media');
select * from finish();
rollback;
